class SkipNode:

    def __init__(self: SkipNode, key: int | None, height: int) -> None:
        if type(height) is not int or height < 1:
            raise ValueError('Height must be a positive integer')
        self.key: int | None = key
        self.forward: list[SkipNode | None] = [None] * height

class SkipList:

    def __init__(self: SkipList, max_level: int=4) -> None:
        if type(max_level) is not int or max_level < 1:
            raise ValueError('max_level must be a positive integer')
        self.max_level: int = max_level
        self.head: SkipNode = SkipNode(None, max_level)
        self.tail: SkipNode | None = None
        self.size: int = 0

    def predecessors(self: SkipList, key: int) -> list[SkipNode]:
        update = [self.head] * self.max_level
        current = self.head
        for level in range(self.max_level - 1, -1, -1):
            while current.forward[level] is not None and current.forward[level].key < key:
                current = current.forward[level]
            update[level] = current
        return update

    def search(self: SkipList, key: int) -> SkipNode | None:
        candidate = self.predecessors(key)[0].forward[0]
        if candidate is not None and candidate.key == key:
            return candidate
        return None

    def insert(self: SkipList, key: int, height: int) -> bool:
        if type(height) is not int or not 1 <= height <= self.max_level:
            raise ValueError('Height out of range')
        update = self.predecessors(key)
        candidate = update[0].forward[0]
        if candidate is not None and candidate.key == key:
            return False
        node = SkipNode(key, height)
        for level in range(height):
            node.forward[level] = update[level].forward[level]
            update[level].forward[level] = node
        if node.forward[0] is None:
            self.tail = node
        self.size += 1
        return True

    def remove(self: SkipList, key: int) -> bool:
        update = self.predecessors(key)
        candidate = update[0].forward[0]
        # Task 1: reject a missing key without changing any links.
        # Task 2: unlink and clear each forward slot in the tower.
        # Task 3: repair tail and size after the unlink.
        return True

def seed_skip(pairs: list[tuple[int, int]], max_level: int=4) -> SkipList:
    """Supplied fixture builder for sorted unique (key, height) pairs."""
    result = SkipList(max_level)
    last = [result.head] * max_level
    previous_key = None
    for key, height in pairs:
        if previous_key is not None and key <= previous_key:
            raise ValueError('Fixture keys must increase')
        if type(height) is not int or not 1 <= height <= max_level:
            raise ValueError('Fixture height out of range')
        node = SkipNode(key, height)
        for level in range(height):
            last[level].forward[level] = node
            last[level] = node
        result.tail = node
        result.size += 1
        previous_key = key
    return result
